package net.civeira.phylax.feature.observe.observabilityconfig.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observabilityconfig.domain.ObservabilityConfig;
import net.civeira.phylax.feature.observe.observabilityconfig.domain.valueobject.RetentionDaysTracesVO;

class RetentionDaysTracesValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of retention days traces of observability config")
  void test_retention_days_traces_value_holder_assign_plain_value() {
    Object holder = new Object();
    RetentionDaysTracesValueHolder<Object> value = new RetentionDaysTracesValueHolder<>(holder);
    Assertions.assertSame(holder, value.retentionDaysTraces(1), "Setters must return the holder");
    Assertions.assertTrue(value.getRetentionDaysTracesValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(1, value.getRetentionDaysTraces().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of retention days traces of observability config")
  void test_retention_days_traces_value_holder_assign_value_object() {
    Object holder = new Object();
    RetentionDaysTracesValueHolder<Object> value = new RetentionDaysTracesValueHolder<>(holder);
    RetentionDaysTracesVO vo = RetentionDaysTracesVO.from(1);
    Assertions.assertFalse(value.getRetentionDaysTracesValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.retentionDaysTraces(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getRetentionDaysTracesValue().orElseThrow());
    Assertions.assertSame(holder, value.retentionDaysTraces(Optional.empty()));
    Assertions.assertFalse(value.getRetentionDaysTracesValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.retentionDaysTraces(Optional.of(vo)));
    Assertions.assertSame(vo, value.getRetentionDaysTracesValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of retention days traces of observability config against the original")
  void test_retention_days_traces_value_holder_read() {
    Object holder = new Object();
    RetentionDaysTracesValueHolder<Object> value = new RetentionDaysTracesValueHolder<>(holder);
    RetentionDaysTracesVO vo = RetentionDaysTracesVO.from(1);
    RetentionDaysTracesVO other = RetentionDaysTracesVO.from(1);
    ObservabilityConfig original = Mockito.mock(ObservabilityConfig.class);
    Mockito.when(original.getRetentionDaysTracesValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readRetentionDaysTraces(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readRetentionDaysTraces(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.retentionDaysTraces(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readRetentionDaysTraces(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readRetentionDaysTraces(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of retention days traces of observability config")
  void test_retention_days_traces_value_holder_unset() {
    Object holder = new Object();
    RetentionDaysTracesValueHolder<Object> value = new RetentionDaysTracesValueHolder<>(holder);
    RetentionDaysTracesVO vo = RetentionDaysTracesVO.from(1);
    value.retentionDaysTraces(vo);
    Assertions.assertSame(holder,
        value.unsetRetentionDaysTracesIfMatches("retentionDaysTraces_other"));
    Assertions.assertTrue(value.getRetentionDaysTracesValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetRetentionDaysTracesIfMatches("retentionDaysTraces"));
    Assertions.assertFalse(value.getRetentionDaysTracesValue().isPresent(),
        "The field name must clear the value");
    value.retentionDaysTraces(vo);
    Assertions.assertSame(holder, value.unsetRetentionDaysTraces());
    Assertions.assertFalse(value.getRetentionDaysTracesValue().isPresent(),
        "Unset must clear the value");
  }
}
